//! The Meshtastic protobufs, generated by prost from the files vendored under
//! `protobufs/`. Which upstream revision those are is in `protobufs/UPSTREAM_REV`,
//! and `scripts/update-protobufs.sh` is how they get replaced.

pub mod wire;

include!(concat!(env!("OUT_DIR"), "/known_fields.rs"));

/// Everything in the `meshtastic` protobuf package.
#[allow(clippy::all, clippy::pedantic, missing_docs)]
pub mod meshtastic {
    include!(concat!(env!("OUT_DIR"), "/meshtastic.rs"));
}

#[cfg(test)]
mod tests {
    use super::meshtastic::{Data, MeshPacket, PortNum, ServiceEnvelope, mesh_packet};
    use prost::Message;

    #[test]
    fn an_envelope_survives_the_round_trip() {
        let packet = MeshPacket {
            from: 0x1234_5678,
            to: 0xffff_ffff,
            id: 42,
            payload_variant: Some(mesh_packet::PayloadVariant::Decoded(Data {
                portnum: PortNum::TextMessageApp as i32,
                payload: b"hola".to_vec(),
                ..Default::default()
            })),
            ..Default::default()
        };
        let envelope = ServiceEnvelope {
            packet: Some(packet.clone()),
            channel_id: "LongFast".into(),
            gateway_id: "!12345678".into(),
        };

        let decoded = ServiceEnvelope::decode(envelope.encode_to_vec().as_slice()).unwrap();

        assert_eq!(decoded.packet, Some(packet));
        assert_eq!(decoded.channel_id, "LongFast");
    }
}
